// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }

    function testFuzz_property(uint256 newMinSum) public {
        // initialize the contract: after this, SetMinSum must be frozen in the reference
        c.Initialized();
        uint256 before = c.MinSum();

        address actor = address(0xA11CE);
        vm.prank(actor);
        bool ok;
        try c.SetMinSum(newMinSum) { ok = true; } catch { ok = false; }

        // Rule: once initialized, SetMinSum always reverts and MinSum is frozen.
        assertTrue(!ok && c.MinSum() == before);
    }
}
